// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzz parameter: whether the callee should revert (true) or succeed (false).
    // The reference contract: forward(...) succeeds iff the callee.call(...) returns true.
    // The mutant that forces `_s = false;` will make forward revert even when the callee would succeed.
    function testFuzz_property(bool calleeShouldRevert) public {
        // Deploy a helper that either reverts or records and succeeds, controlled by the fuzzed bool.
        CalleeHelper helper = new CalleeHelper(calleeShouldRevert);

        // Call forward and observe whether it succeeds or reverts by try/catch.
        bool ok;
        try c.forward(address(helper), abi.encodeWithSignature("ping()")) {
            ok = true;
        } catch {
            ok = false;
        }

        // The rule: the result `ok` must equal the negation of calleeShouldRevert
        // because helper will revert when calleeShouldRevert==true (so forward should fail),
        // and helper will return true (so forward should succeed) when calleeShouldRevert==false.
        // This holds for the correct contract; the mutant that forces `_s = false` will make
        // ok==false even when calleeShouldRevert==false, so the property will fail for that input.
        assertTrue(ok == (!calleeShouldRevert));
    }
}

// A minimal adversarial/observing helper: when shouldRevert==true it reverts in fallback;
// otherwise it exposes a ping() function that returns and records nothing (succeeds).
contract CalleeHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable { shouldRevert = _shouldRevert; }

    // A concrete function that matches the encoded selector used in the test.
    function ping() external {
        if (shouldRevert) revert("boom");
        // succeed (do nothing)
    }

    // Also provide fallback to be robust if call dispatched differently.
    fallback() external payable {
        if (shouldRevert) revert("boom");
    }
    receive() external payable {
        if (shouldRevert) revert("boom");
    }
}
